package com.oac.example.api.generated;

import com.oac.example.api.generated.model.OrderResponse;
import com.oac.example.api.generated.model.AggregateResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

/**
 * Hand-written interface matching the order-service-api.yaml contract.
 * In production, this would be auto-generated by openapi-generator-maven-plugin.
 */
@RequestMapping("/api")
public interface OrdersApi {

    @GetMapping("/orders/{orderId}")
    ResponseEntity<OrderResponse> getOrder(@PathVariable("orderId") String orderId);

    @GetMapping("/orders")
    ResponseEntity<List<OrderResponse>> listOrders();

    @PostMapping("/orders/{orderId}/approve")
    ResponseEntity<OrderResponse> approveOrder(@PathVariable("orderId") String orderId);

    @GetMapping("/orders/aggregate")
    ResponseEntity<AggregateResponse> getAggregate();

    @PostMapping("/seed")
    ResponseEntity<Map<String, Object>> seedSampleData();
}